/// <summary>
///     The <c>AVABPTrackingProspectsService</c> class is the service class for <c>Tracking prospects</c>
/// </summary>
final class AVABPTrackingProspectsService extends SysOperationServiceBase
{
    str     clsPackedQuery;
    Query   clsQuery;

}

Method.Source:
    /// <summary>
///     AVA <c>startOperation</c> method.
/// </summary>
/// <param name="_dataContract">
///     <c>AVABPTrackingProspectsContract</c> as type
/// </param>
public void startOperation(AVABPTrackingProspectsContract _dataContract)
{
    System.Exception ex;
    #OCCRetryCount

    clsQuery        = _dataContract.getQuery();
    clsPackedQuery  = _dataContract.parmPackedQuery();

    try
    {
        this.processOperation();
    }

    catch (Exception::Deadlock)
    {
        retry;
    }

    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }

    catch (Exception::Error)
    {
        error("@NDX:NXAErrorOccured");
        retry;
    }

    catch (Exception::CLRError)
    {
        ex = ClrInterop::getLastException();

        if (ex != null)
        {
            ex = ex.get_InnerException();
            if (ex != null)
            {
                error("@NDX:NXAErrorOccured");
            }
        }

        retry;
    }
}

/// <summary>
///     AVA <c>processOperation</c> method.
/// </summary>
private void processOperation()
{
    Args                            locArgs;
    MenuItemType                    locMenuItemType;
    MenuItemName                    locMenuItemName;
    MenuFunction                    locMenuFunction;

    locMenuItemType = MenuItemType::Display;
    locMenuItemName = menuitemDisplayStr(AVABPTrackingProspectsDisplay);
    locMenuFunction = new MenuFunction(locMenuItemName, locMenuItemType);

    locArgs = new Args();
    locArgs.caller(this);
    locArgs.parm(clsPackedQuery);
    locArgs.menuItemType(locMenuItemType);
    locArgs.menuItemName(locMenuItemName);

    locMenuFunction.openMode(OpenMode::View);
    locMenuFunction.run(locArgs);
}
